sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {
        var assignmentGrpSysId = request.queryParams.groupId;
        if (!assignmentGrpSysId) {
            response.setStatus(400);
            response.setBody({
                error: "groupId is required as query parameter"
            });
            return;
        }

        var uniqueArray = new global.ArrayUtil();

        var assignmentGrpSysIdList = assignmentGrpSysId.toString().split(',');

        var uniqueAssignmentGrpSysIdList = [];
        uniqueAssignmentGrpSysIdList = uniqueArray.unique(assignmentGrpSysIdList);

        var groupInfo = [];

        var grMember = new GlideAggregate('sys_user_grmember');
        grMember.addEncodedQuery('groupIN' + uniqueAssignmentGrpSysIdList);
        grMember.groupBy('group');
        grMember.query();
        while (grMember.next()) {

            var grpData = {};
            grpData.GroupID = grMember.getValue('group');

            var grpMembers = [];

            var grMemberData = new GlideRecord('sys_user_grmember');
            grMemberData.addEncodedQuery('group=' + grMember.getValue('group'));
            grMemberData.query();
            while (grMemberData.next()) {

                var grUser = new GlideRecord('sys_user');
                if (grUser.get(grMemberData.getValue('user'))) {

                    var userInfo = {};
                    userInfo.Name = grUser.getValue('name');
                    userInfo.Email = grUser.getValue('email');
                    userInfo.UserID = grUser.getValue('user_name');
                    grpMembers.push(userInfo);
                }

                grpData.GroupMembers = grpMembers;

            }

            groupInfo.push(grpData);
        }

        response.setStatus(200);
        response.setBody(groupInfo);
        return;

    } catch (e) {
        response.setStatus(400);
        response.setBody({
            error: e.message
        });
        return;
    }

})(request, response);
